<script setup>
import {tripDraft,draftError} from '../state/tripDraft';
import FavoriteButton from '../components/FavoriteButton.vue';
import PlacePicker from '../components/PlacePicker.vue';
import {reactive,ref,computed,watch,onMounted,onUnmounted} from 'vue';
import EditorialPhoto from '../components/EditorialPhoto.vue';
import TravelHeroVideo from '../components/TravelHeroVideo.vue';
import PoeticTheme from '../components/PoeticTheme.vue';
import DestinationGallery from '../components/DestinationGallery.vue';
import {destinations,interests,copy} from '../data/homeEditorial';
import photoCredits from '../../public/images/home/credits.json';
import {t,language} from '../i18n';

import WeatherPanel from '../components/WeatherPanel.vue';
import {resolveDestinations} from '../providers/destinationResolver';
import SearchCalligraphy from '../components/SearchCalligraphy.vue';
import CitySearch from '../components/CitySearch.vue';
import PreferenceSelector from '../components/PreferenceSelector.vue';
const props=defineProps({initial:Object,selectedCity:String,busy:Boolean,searchError:String,progress:String});
const emit=defineEmits(['generate','open-map','cancel','update:selectedCity']);
const form=tripDraft;
const wish=ref(''),error=ref(false);
const weatherDestination=ref(null),weatherOptions=ref([]),weatherLoading=ref(false),weatherError=ref('');let weatherRun=0;
const weatherDates=computed(()=>Array.from({length:Math.min(14,Math.max(1,Number(form.days)||1))},(_,i)=>{const d=new Date(form.date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i);return Number.isFinite(d.getTime())?d.toISOString().slice(0,10):'';}).filter(Boolean));
watch(()=>form.selectedCity,()=>{weatherRun++;weatherDestination.value=null;weatherOptions.value=[];weatherError.value='';weatherLoading.value=false;});
async function queryWeather(){const run=++weatherRun;weatherLoading.value=true;weatherError.value='';try{const options=await resolveDestinations(form.selectedCity);if(run!==weatherRun)return;weatherOptions.value=options;if(options.length===1)weatherDestination.value=options[0];if(!options.length)throw Error();}catch{if(run===weatherRun)weatherError.value=language.value==='zh'?'无法确认目的地，请重试。':'Could not resolve destination. Please retry.';}finally{if(run===weatherRun)weatherLoading.value=false;}}
onUnmounted(()=>weatherRun++);

function addWish(){const name=wish.value.trim();if(name&&!form.wishlist.includes(name))form.wishlist.push(name);wish.value='';}
function payload(){return JSON.parse(JSON.stringify({...form,selectedCity:form.selectedCity.trim()}));}
function valid(){return form.selectedCity.trim()&&form.date&&form.days>=1&&form.days<=14&&form.start<form.end&&Object.values(form.mealWindows).every(w=>w.start<w.end)&&Number.isFinite(form.budget)&&form.budget>=0&&Number.isInteger(form.people)&&form.people>=1&&form.people<=30;}
function submit(){error.value=!valid();if(!error.value)emit('generate',payload());}
function openMap(){error.value=!valid();if(!error.value)emit('open-map',payload());}
const words=computed(()=>copy[language.value]),langIndex=computed(()=>language.value==='zh'?0:1);
const posterFailed=ref(false);
const hero=ref(null),paused=ref(false),reduced=ref(false),selectionNotice=ref(''),videoAvailable=ref(false);let media;
function updateMotion(){reduced.value=media.matches;if(reduced.value)hero.value?.style.setProperty('--drift','0px');}
onMounted(()=>{media=matchMedia('(prefers-reduced-motion: reduce)');updateMotion();media.addEventListener('change',updateMotion);});
onUnmounted(()=>{media?.removeEventListener('change',updateMotion);});
function goPlan(){document.getElementById('trip-planner')?.scrollIntoView({behavior:reduced.value?'instant':'smooth'});document.getElementById('planner-title')?.focus({preventScroll:true});}
function chooseDestination(city){if(props.busy)return;form.selectedCity=language.value==='zh'?city.query:city.queryEn;emit('update:selectedCity',form.selectedCity);goPlan();}
function chooseInterest(id){if(props.busy)return;if(!form.interests.includes(id))form.interests.push(id);selectionNotice.value=id;goPlan();}
function beginJourney(){if(!form.selectedCity.trim()){hero.value?.querySelector('input')?.focus();return;}goPlan();}
</script>
<template><main class="immersive-home hero-intro">
<section ref="hero" class="travel-hero" :class="{paused:paused||reduced}" aria-labelledby="hero-title">
<div class="hero-parallax"><div class="hero-image"><img v-if="!posterFailed" src="/videos/pathly-journey-nov17-poster.webp" :alt="words.scene" fetchpriority="high" @error="posterFailed=true"/><span v-else class="editorial-fallback">{{words.fallback}}</span></div><TravelHeroVideo :paused="paused" @availability="videoAvailable=$event"/></div><div class="hero-shade"></div>
<div class="hero-content"><p class="hero-eyebrow"><span></span> {{words.eyebrow}}</p><h1 id="hero-title"><span class="hero-line hero-line-first">{{words.title}}</span><br/><span class="hero-line hero-line-second">{{words.title2}}</span></h1><p class="hero-subtitle">{{words.subtitle}}</p>
<form class="hero-search" @submit.prevent="beginJourney"><CitySearch v-model="form.selectedCity" @update:model-value="emit('update:selectedCity',$event)"/><button type="submit" :disabled="busy" class="hero-start">{{words.start}} <span>↗</span></button></form>
</div><div class="hero-bottom"><a href="#travel-interests">↓ <span>{{words.scroll}}</span></a><div class="scene-caption"><span>PATHLY JOURNAL</span><p>{{words.scene}}</p><small>{{words.film}}</small></div><button class="motion-toggle" @click="paused=!paused" :disabled="!videoAvailable" :aria-label="paused?words.play:words.pause">{{paused||!videoAvailable?'▷':'Ⅱ'}}</button></div>
</section>
<section id="travel-interests" class="interest-section editorial-section"><div class="section-top"><div><p class="editorial-kicker">01 — {{words.interestLink}}</p><h2>{{words.interestTitle}}</h2></div><p>{{words.interestSub}}</p></div>
<div class="poetic-stories"><PoeticTheme v-for="(item,i) in interests" :key="item.id" :item="item" :index="i" :busy="busy" :selected="form.interests.includes(item.id)" :selected-text="words.selected" @choose="chooseInterest"/></div>
</section>
<section id="travel-destinations" class="dest-section editorial-section"><div class="section-top"><div><p class="editorial-kicker">02 — {{words.destLabel}}</p><h2>{{words.destTitle}}</h2></div><p>{{words.destSub}}</p></div><DestinationGallery :destinations="destinations" :busy="busy" :choose-label="words.choose" @choose="chooseDestination"/></section>
<section id="trip-planner" class="planning-section"><SearchCalligraphy/><aside class="planning-intro"><p class="editorial-kicker">03 — {{words.step}}</p><h2 id="planner-title" tabindex="-1"><template v-if="language==='zh'"><span>把向往，</span><span>安排成旅程。</span></template><template v-else>{{words.planTitle}}</template></h2><p>{{words.planSub}}</p><div class="planning-ink-art" aria-hidden="true"></div></aside><section class="form-panel"><form @submit.prevent="submit"><p v-if="selectionNotice" class="selection-notice" role="status">✓ {{words.applied}} · {{t('planner.interests.'+selectionNotice)}}</p>
<CitySearch v-model="form.selectedCity" @update:model-value="emit('update:selectedCity',$event)"/>
<div class="planning-weather"><button type="button" class="text-button" :disabled="!form.selectedCity.trim()||weatherLoading" @click="queryWeather">{{weatherLoading?(language==='zh'?'正在查询天气…':'Loading weather…'):(language==='zh'?'查询目的地天气 ↗':'Destination weather ↗')}}</button><p v-if="weatherError" role="status">{{weatherError}}</p><div v-if="weatherOptions.length>1&&!weatherDestination"><button type="button" v-for="city in weatherOptions" :key="city.id" @click="weatherDestination=city">{{city.displayName}} · {{city.country}} {{city.region}}</button></div><WeatherPanel v-if="weatherDestination" :destination="weatherDestination" :dates="weatherDates"/></div>
<div class="form-section date-grid"><label class="field">{{t('date')}}<input type="date" v-model="form.date" required/></label><label class="field">{{t('planner.days')}}<input type="number" min="1" max="14" v-model.number="form.days" required/></label><label class="field">{{t('planner.party')}}<select v-model="form.party"><option v-for="(label,id) in t('planner.parties')" :value="id" :key="id">{{label}}</option></select></label></div>
<div class="form-section date-grid"><label class="field">{{t('start')}}<input type="time" v-model="form.start" required/></label><label class="field">{{t('end')}}<input type="time" v-model="form.end" required/></label></div>
<div class="form-section date-grid"><label class="field">{{language==='zh'?'出行人数':'Travellers'}}<input type="number" min="1" max="30" v-model.number="form.people" required/></label><label class="field">{{language==='zh'?'交通偏好':'Transport'}}<select v-model="form.transport"><option value="transit">{{language==='zh'?'公共交通':'Public transport'}}</option><option value="walking">{{language==='zh'?'步行':'Walking'}}</option><option value="driving">{{language==='zh'?'驾车（当前为估算）':'Driving (estimated)'}}</option></select></label></div><div class="form-section"><div class="label-row">{{t('interests')}}</div><PreferenceSelector v-model="form.interests" :options="t('planner.interests')"/></div>
<div class="form-section"><div class="label-row">{{t('planner.pace')}}</div><div class="pace-options"><button v-for="(label,id) in t('planner.paces')" :key="id" type="button" class="chip" :class="{selected:form.pace===id}" :aria-pressed="form.pace===id" @click="form.pace=id"><strong>{{label}}</strong><small>{{t('planner.paceHints.'+id)}}</small></button></div></div>
<div class="form-section walking-row"><span>{{t('walking')}}</span><div class="segmented"><button type="button" v-for="id in ['low','medium','high']" :key="id" :class="{selected:form.walking===id}" :aria-pressed="form.walking===id" @click="form.walking=id">{{t(id)}}</button></div></div>
<div class="form-section"><label class="field">{{t('planner.dailyBudget')}}<input type="number" min="0" max="100000" v-model.number="form.budget" required/></label><small>{{t('planner.budgetHint')}}</small></div>
<div class="form-section"><h3>{{language==='zh'?'入住酒店 / 住宿位置':'Hotel / accommodation'}}</h3><PlacePicker :city="form.selectedCity" kind="hotel" @choose="form.hotel=$event"/><p v-if="form.hotel">{{form.hotel.name}} · {{form.hotel.address}} <FavoriteButton type="hotel" :data="form.hotel"/><button type="button" @click="form.hotel=null">×</button></p></div><div class="form-section"><h3>{{language==='zh'?'想去的餐厅':'Requested restaurants'}}</h3><PlacePicker :city="form.selectedCity" kind="restaurant" @choose="!form.restaurants.some(p=>p.id===$event.id)&&form.restaurants.push($event)"/><p v-for="r in form.restaurants" :key="r.id">{{r.name}} <FavoriteButton type="restaurant" :data="r"/><select v-model="r.mealPreference"><option :value="undefined">{{language==='zh'?'午餐或晚餐':'Either meal'}}</option><option value="LUNCH">{{language==='zh'?'午餐':'Lunch'}}</option><option value="DINNER">{{language==='zh'?'晚餐':'Dinner'}}</option></select><button type="button" @click="form.restaurants=form.restaurants.filter(p=>p.id!==r.id)">×</button></p></div><details class="form-section"><summary>{{language==='zh'?'用餐时间偏好（不是营业时间）':'Meal windows (not business hours)'}}</summary><div v-for="(window,slot) in form.mealWindows" :key="slot" class="form-row"><label class="field">{{slot==='LUNCH'?(language==='zh'?'午餐开始':'Lunch from'):(language==='zh'?'晚餐开始':'Dinner from')}}<input type="time" v-model="window.start"/></label><label class="field">{{language==='zh'?'结束':'Until'}}<input type="time" v-model="window.end"/></label></div></details><div class="wishlist-section"><div class="label-row">{{t('planner.mustOptional')}}</div><p>{{t('planner.mustHint')}}</p><div class="wish-input"><input v-model="wish" :aria-label="t('planner.mustName')" :placeholder="t('planner.mustName')" @keydown.enter.prevent="addWish"/><button type="button" @click="addWish" :disabled="!wish.trim()">{{t('add')}}</button></div><div class="wish-tags"><span v-for="name in form.wishlist" :key="name">{{name}}<button type="button" @click="form.wishlist=form.wishlist.filter(n=>n!==name)" :aria-label="t('remove')+name">×</button></span><span v-for="place in form.mustPlaces" :key="place.id">{{place.name}}<button type="button" @click="form.mustPlaces=form.mustPlaces.filter(p=>p.id!==place.id)" :aria-label="t('remove')+place.name">×</button></span></div><button class="outline" type="button" @click="openMap" :disabled="busy">⌖ {{t('planner.addMust')}}</button></div>
<p v-if="draftError" role="status">{{draftError}}</p><p v-if="error" class="error" role="alert">{{t('invalid')}}</p><p v-if="searchError" class="error" role="alert">{{t(searchError)}}</p><p v-if="busy" role="status">{{t('planner.loading')}} {{progress}}</p><button v-if="busy" type="button" class="outline" @click="emit('cancel')">{{t('livePlan.cancel')}}</button><button class="primary generate" :disabled="busy">{{t('generate')}} ↗</button><p class="form-footnote">{{t('planner.honest')}}</p>
</form></section></section><section class="home-end"><p>{{words.foot}}</p><a href="#hero-title">↑ {{words.start}}</a><details class="photo-credits"><summary>{{words.credits}} · Pexels / Unsplash</summary><p v-for="credit in photoCredits" :key="credit.id"><a :href="credit.source" target="_blank" rel="noopener">{{credit.id}} · {{credit.author}}</a> · <a :href="credit.licenseUrl" target="_blank" rel="noopener">{{credit.license}}</a></p></details></section></main></template>
<style scoped src="./homeEditorial.css"></style>